item.content:encoded:
.ast-primary-header-bar {
    display: none !important;
}

.site-header {
    display: none !important;
}

/* Footer smaller middle column */
.ast-builder-grid-row-3-equal .ast-builder-grid-row {
	grid-template-columns: 4fr 1fr 4fr;
}

/* Footer smaller middle column */
.ast-builder-grid-row-3-equal .ast-builder-grid-row {
	grid-template-columns: 4fr 1fr 4fr;
}

/* Footer smaller middle column */
.ast-builder-grid-row-3-equal .ast-builder-grid-row {
	grid-template-columns: 4fr 1fr 4fr;
}

